import base64, zlib, os, sys, time, shutil, subprocess, pathlib
SMOKE = "0"
NB = ''
root = pathlib.Path("/kaggle/working/proj"); root.mkdir(parents=True, exist_ok=True)
nb_path = root / "FARTransWealth.ipynb"
nb_path.write_bytes(zlib.decompress(base64.b64decode(NB)))
os.environ.update({"FAR_ART": "/kaggle/working/artifacts", "FAR_DATA": "/tmp/far_data", "FAR_SMOKE": SMOKE})
print("notebook written | SMOKE =", SMOKE, flush=True)
import importlib.metadata as md
if md.version("scikit-learn") != "1.6.1":      # frozen models are pickled: pin the version the app and tests use
    r = subprocess.run([sys.executable, "-m", "pip", "install", "-q", "scikit-learn==1.6.1"], capture_output=True, text=True)
    print("pip install scikit-learn==1.6.1 ->", r.returncode, (r.stdout + r.stderr)[-300:], flush=True)
for pkg in ("xgboost", "lightgbm", "shap", "nbformat", "nbclient"):
    try:
        print(pkg, md.version(pkg), flush=True)
    except md.PackageNotFoundError:
        r = subprocess.run([sys.executable, "-m", "pip", "install", "-q", pkg], capture_output=True, text=True); print("pip install", pkg, "->", r.returncode, flush=True)
import nbformat
from nbclient import NotebookClient
from nbclient.exceptions import CellExecutionError
nb = nbformat.read(nb_path, as_version=4)
out = pathlib.Path("/kaggle/working/FARTransWealth.executed.ipynb")
client = NotebookClient(nb, timeout=-1, kernel_name="python3", resources={"metadata": {"path": str(root)}})
t = time.time()
try:
    client.execute(); status = "OK"
except CellExecutionError as e:
    status = "FAILED"; print(str(e)[-3000:], flush=True)
nbformat.write(nb, out)
n_code = sum(c.cell_type == "code" for c in nb.cells)
n_err = sum(1 for c in nb.cells if c.cell_type == "code" for o in c.get("outputs", []) if o.get("output_type") == "error")
print(f"notebook execution {status} in {time.time()-t:.0f}s | code cells {n_code} | error outputs {n_err}", flush=True)
shutil.rmtree(root, ignore_errors=True)
if status != "OK":
    raise SystemExit(1)
